const jobs = new Map(); // job_id -> status ('running' | 'cancelled')

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job with the given job_id. Returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job' }
        },
        required: ['job_id']
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job by job_id. Changes an active job to cancelled. Rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Identifier of the job to cancel' }
        },
        required: ['job_id']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  const { job_id } = args;
  if (name === 'start_job') {
    if (typeof job_id !== 'string' || !job_id) {
      throw new Error('job_id is required');
    }
    if (jobs.get(job_id) === 'running') {
      throw new Error('job already running');
    }
    jobs.set(job_id, 'running');
    return { content: [{ type: 'text', text: `job ${job_id} running` }] };
  }
  if (name === 'cancel_job') {
    if (typeof job_id !== 'string' || !job_id) {
      throw new Error('job_id is required');
    }
    const status = jobs.get(job_id);
    if (status === undefined) {
      throw new Error('job not found');
    }
    if (status === 'cancelled') {
      throw new Error('job already cancelled');
    }
    jobs.set(job_id, 'cancelled');
    return { content: [{ type: 'text', text: `job ${job_id} cancelled` }] };
  }
  throw new Error('Method not found');
}
